<script setup lang="ts">
import { Activity, ArrowRight, RefreshCw } from 'lucide-vue-next';import { onMounted,ref } from 'vue';import { platformDashboardApi } from '@/services/platformFlowDashboard';import type { PlatformDashboardRuntime } from '@/types/platformFlowDashboard'
const loading=ref(false),error=ref(''),dashboard=ref<PlatformDashboardRuntime|null>(null);async function load(){loading.value=true;error.value='';try{dashboard.value=await platformDashboardApi.runtime()}catch(e){error.value=e instanceof Error?e.message:'仪表盘加载失败'}finally{loading.value=false}}onMounted(load)
</script>
<template><section class="workspace"><header class="workspace-heading"><div><h1>{{ dashboard?.name || '平台仪表盘' }}</h1><p>{{ dashboard?.description || '按当前平台权限呈现运行摘要' }}</p></div><a-button :loading="loading" @click="load"><RefreshCw :size="16" />刷新</a-button></header><a-alert v-if="error" type="error" show-icon :message="error"/><div v-if="dashboard" class="metric-grid"><article v-for="item in dashboard.statistics" :key="item.code" class="metric-card"><span>{{ item.label }}</span><strong>{{ item.value }}</strong></article></div><section v-if="dashboard?.health.length" class="panel"><h2><Activity :size="18"/>依赖健康</h2><div class="health-list"><a-tag v-for="item in dashboard.health" :key="item.service" :color="item.state==='UP'?'green':item.state==='DEGRADED'?'orange':'default'">{{ item.service }} · {{ item.state }}</a-tag></div></section><section v-if="dashboard?.quickEntries.length" class="panel"><h2>快捷入口</h2><div class="quick-grid"><RouterLink v-for="entry in dashboard.quickEntries" :key="entry.path" :to="entry.path">{{ entry.label }}<ArrowRight :size="15"/></RouterLink></div></section></section></template>
<style scoped>.metric-grid,.quick-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.metric-card,.panel{padding:18px;border:1px solid #dbe2e8;border-radius:8px;background:#fff}.metric-card{display:grid;gap:8px}.metric-card strong{font-size:30px}.panel{margin-top:16px}.panel h2,.health-list{display:flex;align-items:center;gap:8px}.quick-grid a{display:flex;justify-content:space-between;padding:12px;border:1px solid #e1e7ec;border-radius:6px}</style>
